// Build a risk profile per service from incidents, deployments, metric trends,
// error-log volume, and code churn, then detect recurring failure patterns.
const cfg = $('Set - Config').first().json;
const all = $input.first().json;

const incidentsData = all.incidents || all[0] || {};
const deploysData = all.deployments || all[1] || {};
const metricsData = all.metricsTrend || all[2] || {};
const logsData = all.logsVolume || all[3] || {};
const churnData = all.codeChurn || all[4] || {};

const services = cfg.servicesList.split(',').map(s => s.trim()).filter(Boolean);
const incidents = incidentsData.incidents || (Array.isArray(incidentsData) ? incidentsData : []);
const deployments = deploysData.deployments || (Array.isArray(deploysData) ? deploysData : []);
const metricSeries = metricsData.series || {};
const logSeries = logsData.series || {};
const commits = churnData.items || [];

function daysBetween(a, b) { return Math.abs(a - b) / (1000 * 60 * 60 * 24); }

function trendSlope(points) {
  // points: [{ t: isoString, v: number }] -> naive slope of last vs first half average
  if (!points || points.length < 4) return 0;
  const mid = Math.floor(points.length / 2);
  const firstHalfAvg = points.slice(0, mid).reduce((s, p) => s + p.v, 0) / mid;
  const secondHalfAvg = points.slice(mid).reduce((s, p) => s + p.v, 0) / (points.length - mid);
  if (firstHalfAvg === 0) return secondHalfAvg > 0 ? 100 : 0;
  return Math.round(((secondHalfAvg - firstHalfAvg) / firstHalfAvg) * 100);
}

const profiles = services.map(service => {
  const serviceIncidents = incidents.filter(i => i.service === service);
  const serviceDeploys = deployments.filter(d => d.service === service);
  const failedDeploys = serviceDeploys.filter(d => d.status === 'failed' || d.rolledBack === true);

  const now = Date.now();
  const lastIncidentTs = serviceIncidents.length ? Math.max(...serviceIncidents.map(i => new Date(i.timestamp).getTime())) : null;
  const daysSinceLastIncident = lastIncidentTs ? Math.round(daysBetween(now, lastIncidentTs)) : null;

  const deploymentFailureRate = serviceDeploys.length ? Math.round((failedDeploys.length / serviceDeploys.length) * 100) : 0;

  const errorRateSlope = trendSlope(metricSeries[service]?.errorRate || []);
  const latencySlope = trendSlope(metricSeries[service]?.p95LatencyMs || []);
  const logVolumeSlope = trendSlope(logSeries[service] || []);

  const serviceCommits = commits.filter(c => (c.commit?.message || '').toLowerCase().includes(service.toLowerCase()) || (c.repository?.name || '').toLowerCase().includes(service.toLowerCase()));
  const codeChurnScore = Math.min(100, serviceCommits.length * 4);

  // Recurring pattern: incidents clustered by weekday
  const weekdayCounts = [0, 0, 0, 0, 0, 0, 0];
  serviceIncidents.forEach(i => { weekdayCounts[new Date(i.timestamp).getDay()]++; });
  const maxWeekdayCount = Math.max(...weekdayCounts);
  const dominantWeekday = maxWeekdayCount > 1 ? ['Sun','Mon','Tue','Wed','Thu','Fri','Sat'][weekdayCounts.indexOf(maxWeekdayCount)] : null;

  // Recurring pattern: incident within 48h of a deployment
  const postDeployIncidents = serviceIncidents.filter(inc => {
    const incTs = new Date(inc.timestamp).getTime();
    return serviceDeploys.some(d => {
      const depTs = new Date(d.deployedAt || d.timestamp).getTime();
      return incTs >= depTs && incTs - depTs <= 48 * 60 * 60 * 1000;
    });
  });
  const postDeployIncidentRate = serviceIncidents.length ? Math.round((postDeployIncidents.length / serviceIncidents.length) * 100) : 0;

  return {
    service,
    incidentFrequencyWindow: serviceIncidents.length,
    daysSinceLastIncident,
    deploymentCountWindow: serviceDeploys.length,
    deploymentFailureRate,
    errorRateSlope,
    latencySlope,
    logVolumeSlope,
    codeChurnScore,
    recurringPatterns: {
      dominantWeekday,
      postDeployIncidentRate
    }
  };
});

return [{ json: { ...cfg, profiles } }];

const cfg = $('JS - Build Per-Service Risk Profiles & Detect Recurring Patterns').first().json;
const response = $input.first().json;

const textBlock = (response.content || []).find(b => b.type === 'text');
let parsed = { predictions: [] };
try {
  const raw = (textBlock?.text || '{}').replace(/```json|```/g, '').trim();
  parsed = JSON.parse(raw);
} catch (e) {
  parsed = { predictions: [], parseError: true };
}

const predictions = parsed.predictions || [];
if (predictions.length === 0) {
  return [{ json: { ...cfg, noPredictions: true } }];
}

return predictions.map(p => ({
  json: {
    clickupListId: cfg.clickupListId,
    whatsappBusinessPhoneId: cfg.whatsappBusinessPhoneId,
    whatsappRecipientPhone: cfg.whatsappRecipientPhone,
    incidentLogApiUrl: cfg.incidentLogApiUrl,
    defaultVerificationWindowDays: cfg.defaultVerificationWindowDays,
    highRiskThreshold: cfg.highRiskThreshold,
    mediumRiskThreshold: cfg.mediumRiskThreshold,
    ...p,
    noPredictions: false
  }
}));

