const task = $input.first().json;
// Whichever branch ran (urgent or standard), the prior node's own item already
// carries the full prediction record plus this task's id/url from ClickUp.
return [{
  json: {
    ...task,
    preventiveTaskId: task.id,
    preventiveTaskUrl: task.url
  }
}];

const prediction = $('JS - Attach Task Id to Prediction Record').first().json;
const all = $input.first().json;

const incidentCheck = all.incidents || all[0] || {};
const taskStatus = all.task || all[1] || {};

const incidentsSince = incidentCheck.incidents || (Array.isArray(incidentCheck) ? incidentCheck : []);
const incidentOccurred = incidentsSince.length > 0;
const taskCompleted = (taskStatus.status?.status || '').toLowerCase() === 'complete' || (taskStatus.status?.status || '').toLowerCase() === 'done';

return [{
  json: {
    ...prediction,
    incidentOccurred,
    incidentsSinceCount: incidentsSince.length,
    taskCompleted
  }
}];
